    35	    String writeLivingCells(Set<Cell> livingCells) throws IOException {
    36	        ObjectNode response = mapper.createObjectNode();
    37	        ArrayNode aliveCells = response.putArray(ALIVE_CELLS);
    38	        for (Cell cell : sortedByXThenY(livingCells)) {
    39	            ArrayNode coordinates = aliveCells.addArray();
    40	            coordinates.add(cell.x());
    41	            coordinates.add(cell.y());
    42	        }
    43	        return mapper.writeValueAsString(response);
    44	    }
    45	
    46	    private static List<Cell> sortedByXThenY(Set<Cell> livingCells) {
    47	        List<Cell> sorted = new ArrayList<>(livingCells);
    48	        sorted.sort(Comparator.comparingInt(Cell::x).thenComparingInt(Cell::y));
    49	        return sorted;
    50	    }
    51	}
